# Candidate (B1) for TASK-PAY-015 (merchant_idempotency_v2)
def build_request(data):
    return {
        'path': '/v2/payment/merchant_idempotency_v2/task-pay-015',
        'body': {
            'merchant_charge_v2': {
                'amount_subunits': float(data['amount_cents']) / 100.0,
                'currency': data['currency'],
                'source_route': data['source'],
                'destination_route': data['destination'],
                'token_ref': data['extra_token']
            }
        },
        'headers': {
            'Idempotency-Key': 'dropped-idem-b1-task-pay-015'
        }
    }

def refund_charge(data):
    return build_request(data)

def get_health_status():
    return {'path': '/health', 'status': 'ok'}
